std::string protoConverter::removeSpecial(const std::string &x)
{
        std::string tmp(x);
        if (!tmp.empty())
                tmp.erase(std::remove_if(tmp.begin(), tmp.end(),
                                         [](char c) { return !(std::isalpha(c) || std::isdigit(c)); } ), tmp.end());
        return tmp;
}

void protoConverter::visit(ArrType const& x)
{
        if (x.elements_size() > 0) {
                int i = x.elements_size();
                m_output << "[";
                for (auto &e : x.elements()) {
                        i--;
                        if (i == 0) {
                                visit(e);
                        } else {
                                visit(e);
                                m_output << ", ";
                        }
                }
                m_output << "]";
        } else {
                m_output << "[1]";
        }
}

void protoConverter::visit(Array const& x)
{
        switch (x.arr_func()) {
                case Array::FLATTEN:
                        visit(x.arr_arg());
                        m_output << ".flatten";
                        break;
                case Array::COMPACT:
                        visit(x.arr_arg());
                        m_output << ".compact";
                        break;
                case Array::FETCH:
                        visit(x.arr_arg());
                        m_output << ".fetch";
                        break;
                case Array::FILL:
                        visit(x.arr_arg());
                        m_output << ".fill";
                        break;
                case Array::ROTATE:
                        visit(x.arr_arg());
                        m_output << ".rotate";
                        break;
                case Array::ROTATE_E:
                        visit(x.arr_arg());
                        m_output << ".rotate!";
                        break;
                case Array::DELETEIF:
                        visit(x.arr_arg());
                        m_output << ".delete_if";
                        break;
                case Array::INSERT:
                        visit(x.arr_arg());
                        m_output << ".insert";
                        break;
                case Array::BSEARCH:
                        visit(x.arr_arg());
                        m_output << ".bsearch";
                        break;
                case Array::KEEPIF:
                        visit(x.arr_arg());
                        m_output << ".keep_if";
                        break;
                case Array::SELECT:
                        visit(x.arr_arg());
                        m_output << ".select";
                        break;
                case Array::VALUES_AT:
                        visit(x.arr_arg());
                        m_output << ".values_at";
                        break;
                case Array::BLOCK:
                        visit(x.arr_arg());
                        m_output << ".index";
                        break;
                case Array::DIG:
                        visit(x.arr_arg());
                        m_output << ".dig";
                        break;
                case Array::SLICE:
                        visit(x.arr_arg());
                        m_output << ".slice";
                        break;
                case Array::PERM:
                        visit(x.arr_arg());
                        m_output << ".permutation";
                        break;
                case Array::COMB:
                        visit(x.arr_arg());
                        m_output << ".combination";
                        break;
                case Array::ASSOC:
                        visit(x.arr_arg());
                        m_output << ".assoc";
                        break;
                case Array::RASSOC:
                        visit(x.arr_arg());
                        m_output << ".rassoc";
                        break;
        }
        m_output << "(";
        visit(x.val_arg());
        m_output << ")";
}

void protoConverter::visit(AssignmentStatement const& x)
{
        m_output << "var_" << m_numLiveVars << " = ";
        visit(x.rvalue());
        m_numVarsPerScope.top()++;
        m_numLiveVars++;
        m_output << "\n";
}

void protoConverter::visit(BinaryOp const& x)
{
        m_output << "(";
        visit(x.left());
        switch (x.op()) {
                case BinaryOp::ADD: m_output << " + "; break;
                case BinaryOp::SUB: m_output << " - "; break;
                case BinaryOp::MUL: m_output << " * "; break;
                case BinaryOp::DIV: m_output << " / "; break;
                case BinaryOp::MOD: m_output << " % "; break;
                case BinaryOp::XOR: m_output << " ^ "; break;
                case BinaryOp::AND: m_output << " and "; break;
                case BinaryOp::OR: m_output << " or "; break;
                case BinaryOp::EQ: m_output << " == "; break;
                case BinaryOp::NE: m_output << " != "; break;
                case BinaryOp::LE: m_output << " <= "; break;
                case BinaryOp::GE: m_output << " >= "; break;
                case BinaryOp::LT: m_output << " < "; break;
                case BinaryOp::GT: m_output << " > "; break;
                case BinaryOp::RS: m_output << " >> "; break;
        }
        visit(x.right());
        m_output << ")";
}

void protoConverter::visit(BuiltinFuncs const& x)
{
        switch (x.bifunc_oneof_case()) {
                case BuiltinFuncs::kOs:
                        visit(x.os());
                        break;
                case BuiltinFuncs::kTime:
                        visit(x.time());
                        break;
                case BuiltinFuncs::kArr:
                        visit(x.arr());
                        break;
                case BuiltinFuncs::kMops:
                        visit(x.mops());
                        break;
                case BuiltinFuncs::BIFUNC_ONEOF_NOT_SET:
                        m_output << "1";
                        break;
        }
        m_output << "\n";
}

void protoConverter::visit(Const const& x)
{
        switch (x.const_oneof_case()) {
                case Const::kIntLit:
                        m_output << "(" << (x.int_lit() % 13) << ")";
                        break;
                case Const::kBoolVal:
                        m_output << "(" << x.bool_val() << ")";
                        break;
                case Const::CONST_ONEOF_NOT_SET:
                        m_output << "1";
                        break;
        }
}

void protoConverter::visit(Function const& x)
{
        m_output << "def foo()\nvar_0 = 1\n";
        visit(x.statements());
        m_output << "end\n";
        m_output << "foo\n";
}

void protoConverter::visit(HashType const& x)
{
        if (x.keyval_size() > 0) {
                int i = x.keyval_size();
                m_output << "{";
                for (auto &e : x.keyval()) {
                        i--;
                        if (i == 0) {
                                visit(e);
                        }
                        else {
                                visit(e);
                                m_output << ", ";
                        }
                }
                m_output << "}";
        }
}

